// Drop rows missing required numeric fields or order_id
const required = ['order_id','date','revenue','gross_profit','quantity','unit_price','unit_cost'];
const valid = [];
const invalid = [];

for (const item of $input.all()) {
  const r = item.json;
  const ok = required.every(k => r[k] !== '' && r[k] !== null && r[k] !== undefined);
  const numOk = ['revenue','gross_profit','quantity','unit_price','unit_cost','cogs']
    .every(k => !isNaN(parseFloat(r[k])));
  if (ok && numOk) valid.push({ json: r });
  else invalid.push(r.order_id || 'unknown');
}

if (invalid.length) {
  console.log(`Skipped ${invalid.length} invalid rows: ${invalid.join(', ')}`);
}

if (valid.length === 0) throw new Error('No valid rows found in CSV.');

return valid;

// Sort rows by gross_profit descending
const rows = $input.all().map(i => ({
  ...i.json,
  quantity:         parseInt(i.json.quantity)              || 0,
  unit_price:       parseFloat(i.json.unit_price)          || 0,
  unit_cost:        parseFloat(i.json.unit_cost)           || 0,
  discount_pct:     parseFloat(i.json.discount_pct)        || 0,
  revenue:          parseFloat(i.json.revenue)             || 0,
  cogs:             parseFloat(i.json.cogs)                || 0,
  gross_profit:     parseFloat(i.json.gross_profit)        || 0,
  gross_margin_pct: parseFloat(i.json.gross_margin_pct)    || 0
}));

rows.sort((a, b) => b.gross_profit - a.gross_profit);

return rows.map(r => ({ json: r }));

// Compute all KPIs from sorted rows
const rows = $input.all().map(i => i.json);

const totalRevenue  = rows.reduce((s, r) => s + r.revenue, 0);
const totalCOGS     = rows.reduce((s, r) => s + r.cogs, 0);
const totalProfit   = rows.reduce((s, r) => s + r.gross_profit, 0);
const avgMargin     = totalRevenue > 0 ? (totalProfit / totalRevenue) * 100 : 0;
const totalOrders   = rows.length;
const totalUnits    = rows.reduce((s, r) => s + r.quantity, 0);
const avgOrderValue = totalRevenue / totalOrders;
const bestOrder     = rows[0];

return [{ json: {
  rows,
  kpis: {
    totalRevenue:    parseFloat(totalRevenue.toFixed(2)),
    totalCOGS:       parseFloat(totalCOGS.toFixed(2)),
    totalProfit:     parseFloat(totalProfit.toFixed(2)),
    avgMarginPct:    parseFloat(avgMargin.toFixed(2)),
    totalOrders,
    totalUnits,
    avgOrderValue:   parseFloat(avgOrderValue.toFixed(2)),
    bestOrderId:     bestOrder.order_id,
    bestOrderProfit: bestOrder.gross_profit
  },
  generatedAt: new Date().toISOString()
}}];

// Aggregate revenue, profit and orders by product category
const { rows } = $input.first().json;
const map = {};
rows.forEach(r => {
  if (!map[r.category]) map[r.category] = { category: r.category, revenue: 0, cogs: 0, gross_profit: 0, orders: 0, units: 0 };
  map[r.category].revenue      += r.revenue;
  map[r.category].cogs         += r.cogs;
  map[r.category].gross_profit += r.gross_profit;
  map[r.category].orders       += 1;
  map[r.category].units        += r.quantity;
});
const result = Object.values(map)
  .sort((a, b) => b.revenue - a.revenue)
  .map(d => ({
    ...d,
    revenue:      parseFloat(d.revenue.toFixed(2)),
    cogs:         parseFloat(d.cogs.toFixed(2)),
    gross_profit: parseFloat(d.gross_profit.toFixed(2)),
    margin_pct:   parseFloat((d.gross_profit / d.revenue * 100).toFixed(2))
  }));
return [{ json: { byCategory: result } }];

// Aggregate revenue, profit and orders by sales region
const { rows } = $input.first().json;
const map = {};
rows.forEach(r => {
  if (!map[r.region]) map[r.region] = { region: r.region, revenue: 0, gross_profit: 0, orders: 0, units: 0 };
  map[r.region].revenue      += r.revenue;
  map[r.region].gross_profit += r.gross_profit;
  map[r.region].orders       += 1;
  map[r.region].units        += r.quantity;
});
const result = Object.values(map)
  .sort((a, b) => b.revenue - a.revenue)
  .map(d => ({
    ...d,
    revenue:      parseFloat(d.revenue.toFixed(2)),
    gross_profit: parseFloat(d.gross_profit.toFixed(2)),
    margin_pct:   parseFloat((d.gross_profit / d.revenue * 100).toFixed(2))
  }));
return [{ json: { byRegion: result } }];

// Aggregate revenue and profit per calendar month
const { rows } = $input.first().json;
const map = {};
rows.forEach(r => {
  const month = r.date.slice(0, 7);
  if (!map[month]) map[month] = { month, revenue: 0, gross_profit: 0, orders: 0 };
  map[month].revenue      += r.revenue;
  map[month].gross_profit += r.gross_profit;
  map[month].orders       += 1;
});
const result = Object.values(map)
  .sort((a, b) => a.month.localeCompare(b.month))
  .map(d => ({
    ...d,
    revenue:      parseFloat(d.revenue.toFixed(2)),
    gross_profit: parseFloat(d.gross_profit.toFixed(2)),
    margin_pct:   parseFloat((d.gross_profit / d.revenue * 100).toFixed(2))
  }));
return [{ json: { monthly: result } }];

// Top 5 products by revenue + salesperson leaderboard + channel breakdown
const { rows } = $input.first().json;

const byProduct = {};
rows.forEach(r => {
  if (!byProduct[r.product_name]) byProduct[r.product_name] = { product: r.product_name, category: r.category, revenue: 0, gross_profit: 0, units: 0 };
  byProduct[r.product_name].revenue      += r.revenue;
  byProduct[r.product_name].gross_profit += r.gross_profit;
  byProduct[r.product_name].units        += r.quantity;
});
const top5 = Object.values(byProduct)
  .sort((a, b) => b.revenue - a.revenue)
  .slice(0, 5)
  .map(d => ({
    ...d,
    revenue:      parseFloat(d.revenue.toFixed(2)),
    gross_profit: parseFloat(d.gross_profit.toFixed(2)),
    margin_pct:   parseFloat((d.gross_profit / d.revenue * 100).toFixed(2))
  }));

const bySales = {};
rows.forEach(r => {
  if (!bySales[r.salesperson]) bySales[r.salesperson] = { salesperson: r.salesperson, revenue: 0, gross_profit: 0, orders: 0 };
  bySales[r.salesperson].revenue      += r.revenue;
  bySales[r.salesperson].gross_profit += r.gross_profit;
  bySales[r.salesperson].orders       += 1;
});
const leaderboard = Object.values(bySales)
  .sort((a, b) => b.revenue - a.revenue)
  .map(d => ({
    ...d,
    revenue:      parseFloat(d.revenue.toFixed(2)),
    gross_profit: parseFloat(d.gross_profit.toFixed(2)),
    margin_pct:   parseFloat((d.gross_profit / d.revenue * 100).toFixed(2))
  }));

const byChannel = {};
rows.forEach(r => {
  if (!byChannel[r.channel]) byChannel[r.channel] = { channel: r.channel, revenue: 0, gross_profit: 0, orders: 0 };
  byChannel[r.channel].revenue      += r.revenue;
  byChannel[r.channel].gross_profit += r.gross_profit;
  byChannel[r.channel].orders       += 1;
});
const channels = Object.values(byChannel).sort((a, b) => b.revenue - a.revenue);

return [{ json: { top5Products: top5, leaderboard, channels } }];

// Flatten sorted rows into individual items for Google Sheets tab
const { rows } = $('Calculate KPIs').first().json;
return rows.map(r => ({ json: r }));

// Build KPI summary rows for Google Sheets tab
const kpis = $('Calculate KPIs').first().json.kpis;
const merged = $input.first().json;
const { byCategory, byRegion, monthly, top5Products, leaderboard, channels } = merged;

const fmt = v => Number(v).toFixed(2);
const rows = [
  { section: 'KPI',        metric: 'Total Revenue',    value: `$${fmt(kpis.totalRevenue)}` },
  { section: 'KPI',        metric: 'Total COGS',        value: `$${fmt(kpis.totalCOGS)}` },
  { section: 'KPI',        metric: 'Gross Profit',      value: `$${fmt(kpis.totalProfit)}` },
  { section: 'KPI',        metric: 'Avg Margin',        value: `${fmt(kpis.avgMarginPct)}%` },
  { section: 'KPI',        metric: 'Total Orders',      value: kpis.totalOrders },
  { section: 'KPI',        metric: 'Units Sold',        value: kpis.totalUnits },
  { section: 'KPI',        metric: 'Avg Order Value',   value: `$${fmt(kpis.avgOrderValue)}` },
  { section: 'KPI',        metric: 'Best Order ID',     value: kpis.bestOrderId },
  ...(byCategory || []).map(d => ({ section: 'Category',    metric: d.category,      value: `Rev $${fmt(d.revenue)} | Profit $${fmt(d.gross_profit)} | Margin ${d.margin_pct}%` })),
  ...(byRegion   || []).map(d => ({ section: 'Region',      metric: d.region,        value: `Rev $${fmt(d.revenue)} | Profit $${fmt(d.gross_profit)} | Orders ${d.orders}` })),
  ...(monthly    || []).map(d => ({ section: 'Monthly',     metric: d.month,         value: `Rev $${fmt(d.revenue)} | Profit $${fmt(d.gross_profit)}` })),
  ...(top5Products || []).map(d => ({ section: 'Top Product',  metric: d.product,   value: `Rev $${fmt(d.revenue)} | Margin ${d.margin_pct}%` })),
  ...(leaderboard  || []).map(d => ({ section: 'Salesperson',  metric: d.salesperson, value: `Rev $${fmt(d.revenue)} | Orders ${d.orders}` })),
  ...(channels     || []).map(d => ({ section: 'Channel',      metric: d.channel,   value: `Rev $${fmt(d.revenue)} | Orders ${d.orders}` }))
];
return rows.map(r => ({ json: r }));

// Build the full HTML report string from all aggregations
const kpisData  = $('Calculate KPIs').first().json;
const merged    = $('Merge Aggregations').first().json;
const { kpis, rows } = kpisData;
const { byCategory, byRegion, monthly, top5Products, leaderboard, channels } = merged;

const fmt    = v => Number(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const fmtPct = v => Number(v).toFixed(1) + '%';
const today  = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });

const catRows  = (byCategory || []).map(d => `<tr><td>${d.category}</td><td class="num">$${fmt(d.revenue)}</td><td class="num">$${fmt(d.gross_profit)}</td><td class="num">${fmtPct(d.margin_pct)}</td><td class="num">${d.orders}</td></tr>`).join('');
const regRows  = (byRegion   || []).map(d => `<tr><td>${d.region}</td><td class="num">$${fmt(d.revenue)}</td><td class="num">$${fmt(d.gross_profit)}</td><td class="num">${fmtPct(d.margin_pct)}</td><td class="num">${d.orders}</td></tr>`).join('');
const monRows  = (monthly    || []).map(d => `<tr><td>${d.month}</td><td class="num">$${fmt(d.revenue)}</td><td class="num">$${fmt(d.gross_profit)}</td><td class="num">${fmtPct(d.margin_pct)}</td><td class="num">${d.orders}</td></tr>`).join('');
const top5Rows = (top5Products||[]).map(d => `<tr><td>${d.product}</td><td>${d.category}</td><td class="num">${d.units}</td><td class="num">$${fmt(d.revenue)}</td><td class="num">$${fmt(d.gross_profit)}</td><td class="num">${fmtPct(d.margin_pct)}</td></tr>`).join('');
const leadRows = (leaderboard ||[]).map((d,i) => `<tr><td><strong>#${i+1}</strong> ${d.salesperson}</td><td class="num">$${fmt(d.revenue)}</td><td class="num">$${fmt(d.gross_profit)}</td><td class="num">${fmtPct(d.margin_pct)}</td><td class="num">${d.orders}</td></tr>`).join('');
const chanRows = (channels    ||[]).map(d => `<tr><td>${d.channel}</td><td class="num">$${fmt(d.revenue)}</td><td class="num">$${fmt(d.gross_profit)}</td><td class="num">${d.orders}</td></tr>`).join('');
const orderRows= (rows||[]).slice(0,10).map(r => `<tr><td>${r.order_id}</td><td>${r.date}</td><td>${r.product_name}</td><td class="num">${r.quantity}</td><td class="num">$${fmt(r.revenue)}</td><td class="num">$${fmt(r.gross_profit)}</td><td class="num">${r.gross_margin_pct}%</td><td>${r.region}</td><td>${r.salesperson}</td></tr>`).join('');

