return [{ json: { html, today, generatedAt: kpisData.generatedAt } }];

// Convert HTML string to a base64 binary so Gotenberg can receive it as multipart
const { html, today, generatedAt } = $input.first().json;
const buf = Buffer.from(html, 'utf8');
return [{
  json: { today, generatedAt },
  binary: {
    reportFile: {
      data:          buf.toString('base64'),
      mimeType:      'text/html',
      fileName:      'index.html',
      fileExtension: 'html'
    }
  }
}];

// Rename the PDF binary to a dated filename
const item = $input.first();
const dateStr = new Date().toISOString().slice(0, 10);
const fileName = `Sales_Report_${dateStr}.pdf`;

const pdfBinary = item.binary?.pdfFile;
if (!pdfBinary) throw new Error('No pdfFile binary from Gotenberg.');

return [{
  json:   { fileName, dateStr },
  binary: {
    pdfFile: { ...pdfBinary, fileName, fileExtension: 'pdf' }
  }
}];

// Prepare email subject, preview text and metadata
const { fileName, dateStr } = $input.first().json;
const kpis = $('Calculate KPIs').first().json.kpis;

const fmt = v => Number(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

return [{
  json: {
    subject:     `Sales & Products Report — ${new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}`,
    previewText: `Revenue $${fmt(kpis.totalRevenue)} | Profit $${fmt(kpis.totalProfit)} | Margin ${kpis.avgMarginPct}% | ${kpis.totalOrders} orders`,
    fileName,
    dateStr,
    kpis
  },
  binary: $input.first().binary
}];

// Log execution summary
