  completedAt:   new Date().toISOString(),
  pdfFileName:   meta.fileName,
  totalRevenue:  `$${fmt(kpis.totalRevenue)}`,
  grossProfit:   `$${fmt(kpis.totalProfit)}`,
  avgMargin:     `${kpis.avgMarginPct}%`,
  totalOrders:   kpis.totalOrders,
  unitsSold:     kpis.totalUnits,
  sheetsUpdated: 2
};

